import type {SidebarsConfig} from '@docusaurus/plugin-content-docs';

// Sidebar for the `operator` docs plugin instance (versioned). One named sidebar
// (`operatorSidebar`) autogenerated from the current version's operator/ folder;
// each released version reuses the same id via its
// operator_versioned_sidebars/version-<v>-sidebars.json stub, resolved against
// that version's docs dir. The folder tree (and each _category_.json) mirrors
// the Antora nav.adoc, so autogeneration reproduces the sidebar order.
const sidebars: SidebarsConfig = {
  operatorSidebar: [{type: 'autogenerated', dirName: '.'}],
};

export default sidebars;
